content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: #0f172a;
  color: #f8fafc;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 800px;
  height: 100vh;
  max-height: 850px;
  background: #1e293b;
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 10px 10px -5px rgba(0, 0, 0, 0.4);
  border-radius: 12px;
  overflow: hidden;
  border: 1px solid #334155;
}

.canvas-wrapper {
  flex: 1;
  position: relative;
  background: #090d16;
  overflow: hidden;
  cursor: crosshair;
}

.canvas-element {
  display: block;
  width: 100%;
  height: 100%;
}

.controls-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 24px;
  background: #1e293b;
  border-top: 1px solid #334155;
}

.slider-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: #94a3b8;
}

.slider-group label {
  display: flex;
  justify-content: space-between;
  font-weight: 500;
}

.slider-group input[type="range"] {
  width: 120px;
  accent-color: #3b82f6;
  cursor: pointer;
}

.btn {
  background-color: #3b82f6;
  color: white;
  border: none;
  padding: 8px 16px;
  border-radius: 6px;
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:hover {
  background-color: #2563eb;
}

.btn:active {
  transform: scale(0.98);
}

.btn-danger {
  background-color: #ef4444;
}

.btn-danger:hover {
  background-color: #dc2626;
}

.stats {
  font-size: 14px;
  font-weight: 500;
  color: #cbd5e1;
  background: #0f172a;
  padding: 6px 12px;
  border-radius: 6px;
  border: 1px solid #334155;
}

@media (max-width: 600px) {
  .app-container {
    height: 100vh;
    max-height: none;
    border-radius: 0;
    border: none;
  }

  .controls-bar {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .slider-group input[type="range"] {
    width: 100%;
  }
}

export interface Ball {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
}

export interface PhysicsParams {
  gravity: number;
  bounce: number;
  friction: number;
}

import { useState, useCallback } from 'react';
import { Ball, PhysicsParams } from './types';
import PhysicsCanvas from './PhysicsCanvas';
import Controls from './Controls';

export default function App() {
  const [balls, setBalls] = useState<Ball[]>([
    { id: 1, x: 150, y: 100, vx: 2, vy: 0, radius: 20, color: '#3b82f6' },
    { id: 2, x: 300, y: 150, vx: -3, vy: 1, radius: 25, color: '#ef4444' },
    { id: 3, x: 450, y: 200, vx: 1, vy: -2, radius: 18, color: '#10b981' },
  ]);

  const [params, setParams] = useState<PhysicsParams>({
    gravity: 0.5,
    bounce: 0.7,
    friction: 0.99,
  });

  const handleAddBall = useCallback((x: number, y: number) => {
    const colors = ['#3b82f6', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6', '#ec4899'];
    const newBall: Ball = {
      id: Date.now() + Math.random(),
      x,
      y,
      vx: (Math.random() - 0.5) * 8,
      vy: (Math.random() - 0.5) * 4,
      radius: Math.floor(Math.random() * 15) + 12,
      color: colors[Math.floor(Math.random() * colors.length)],
    };
    setBalls((prev) => [...prev, newBall]);
  }, []);

  const handleClearBalls = useCallback(() => {
    setBalls([]);
  }, []);

  const handleParamChange = useCallback((key: keyof PhysicsParams, value: number) => {
    setParams((prev) => ({ ...prev, [key]: value }));
  }, []);

  return (
    <div className="app-container">
      <div className="canvas-wrapper">
        <PhysicsCanvas
          balls={balls}
          setBalls={setBalls}
          params={params}
          onAddBall={handleAddBall}
        />
      </div>
      <Controls
        ballsCount={balls.length}
        params={params}
        onParamChange={handleParamChange}
        onClear={handleClearBalls}
      />
    </div>
  );
}

import { useEffect, useRef, Dispatch, SetStateAction } from 'react';
import { Ball, PhysicsParams } from './types';

interface PhysicsCanvasProps {
  balls: Ball[];
  setBalls: Dispatch<SetStateAction<Ball[]>>;
  params: PhysicsParams;
  onAddBall: (x: number, y: number) => void;
}

export default function PhysicsCanvas({ balls, setBalls, params, onAddBall }: PhysicsCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const ballsRef = useRef<Ball[]>(balls);
  const paramsRef = useRef<PhysicsParams>(params);

  useEffect(() => {
    ballsRef.current = balls;
  }, [balls]);

  useEffect(() => {
    paramsRef.current = params;
  }, [params]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const resizeCanvas = () => {
      const parent = canvas.parentElement;
      if (parent) {
        canvas.width = parent.clientWidth;
        canvas.height = parent.clientHeight;
      }
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    const updatePhysics = () => {
      const width = canvas.width;
      const height = canvas.height;
      const { gravity, bounce, friction } = paramsRef.current;

      const updatedBalls = ballsRef.current.map((ball) => {
        let { x, y, vx, vy, radius } = ball;

        vy += gravity;
        vx *= friction;
        vy *= friction;

        x += vx;
        y += vy;

        if (x - radius < 0) {
          x = radius;
          vx = -vx * bounce;
        } else if (x + radius > width) {
          x = width - radius;
          vx = -vx * bounce;
        }

        if (y - radius < 0) {
          y = radius;
          vy = -vy * bounce;
        } else if (y + radius > height) {
          y = height - radius;
          vy = -vy * bounce;
          if (Math.abs(vy) < gravity) vy = 0;
        }

        return { ...ball, x, y, vx, vy };
      });

      for (let i = 0; i < updatedBalls.length; i++) {
        for (let j = i + 1; j < updatedBalls.length; j++) {
          const b1 = updatedBalls[i];
          const b2 = updatedBalls[j];
          const dx = b2.x - b1.x;
          const dy = b2.y - b1.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          const minDist = b1.radius + b2.radius;

          if (dist < minDist && dist > 0) {
            const overlap = (minDist - dist) / 2;
            const nx = dx / dist;
            const ny = dy / dist;

            b1.x -= nx * overlap;
            b1.y -= ny * overlap;
            b2.x += nx * overlap;
            b2.y += ny * overlap;

            const kx = b1.vx - b2.vx;
            const ky = b1.vy - b2.vy;
            const p = (nx * kx + ny * ky);

            b1.vx -= p * nx * paramsRef.current.bounce;
            b1.vy -= p * ny * paramsRef.current.bounce;
            b2.vx += p * nx * paramsRef.current.bounce;
            b2.vy += p * ny * paramsRef.current.bounce;
          }
        }
      }

      setBalls(updatedBalls);
    };

    const render = () => {
      updatePhysics();

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ballsRef.current.forEach((ball) => {
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
        ctx.fillStyle = ball.color;
        ctx.shadowColor = ball.color;
        ctx.shadowBlur = 8;
        ctx.fill();
        ctx.closePath();
        ctx.shadowBlur = 0;
      });

      animationFrameId = requestAnimationFrame(render);
    };

    animationFrameId = requestAnimationFrame(render);

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', resizeCanvas);
    };
  }, [setBalls]);

  const handleClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    onAddBall(x, y);
  };

  return (
    <canvas
      ref={canvasRef}
      className="canvas-element"
      onClick={handleClick}
    />
  );
}

import { PhysicsParams } from './types';

interface ControlsProps {
  ballsCount?: number;
  params: PhysicsParams;
  onParamChange: (key: keyof PhysicsParams, value: number) => void;
  onClear?: () => void;
}

export default function Controls({ ballsCount = 0, params, onParamChange, onClear }: ControlsProps) {
  return (
    <div className="controls-bar">
      <div className="slider-group">
        <label>
          重力: <span>{params.gravity.toFixed(1)}</span>
        </label>
        <input
          type="range"
          min="0"
          max="2"
          step="0.1"
          value={params.gravity}
          onChange={(e) => onParamChange('gravity', parseFloat(e.target.value))}
        />
      </div>

      <div className="slider-group">
        <label>
          反発係数: <span>{params.bounce.toFixed(2)}</span>
        </label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.05"
          value={params.bounce}
          onChange={(e) => onParamChange('bounce', parseFloat(e.target.value))}
        />
      </div>

      <div className="slider-group">
        <label>
          摩擦: <span>{params.friction.toFixed(3)}</span>
        </label>
        <input
          type="range"
          min="0.95"
          max="1"
          step="0.001"
          value={params.friction}
          onChange={(e) => onParamChange('friction', parseFloat(e.target.value))}
        />
      </div>

      <div className="stats">
        ボール数: {ballsCount}
      </div>

      <button className="btn btn-danger" onClick={() => onClear?.()}>
        全消去
      </button>
    </div>
  );
}
